-- Table: categories
CREATE TABLE categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, parent_id TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);

-- Datos (18 registros)

-- Table: sellers
CREATE TABLE sellers (
        id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
        full_name TEXT NOT NULL,
        email TEXT NOT NULL UNIQUE,
        phone TEXT NOT NULL,
        id_number TEXT NOT NULL UNIQUE,
        password_hash TEXT NOT NULL,
        assigned_series_id TEXT,
        is_active BOOLEAN NOT NULL DEFAULT TRUE,
        created_at TEXT DEFAULT (datetime('now'))
      );

-- Datos (6 registros)

-- Table: invoice_counters
CREATE TABLE invoice_counters (
        id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
        prefix_letter TEXT NOT NULL,
        city_letter TEXT NOT NULL,
        current_number INTEGER NOT NULL DEFAULT 0,
        max_number INTEGER NOT NULL DEFAULT 99999,
        is_active BOOLEAN NOT NULL DEFAULT TRUE,
        created_at TEXT DEFAULT (datetime('now'))
      );

-- Datos (2 registros)

-- Table: sale_items
CREATE TABLE sale_items (id TEXT PRIMARY KEY, sale_id TEXT NOT NULL, product_id TEXT NOT NULL, quantity INTEGER NOT NULL, unit_price REAL NOT NULL, subtotal REAL NOT NULL, FOREIGN KEY (sale_id) REFERENCES sales(id), FOREIGN KEY (product_id) REFERENCES catalog(id));


-- Table: invoices
CREATE TABLE invoices (id TEXT PRIMARY KEY, sale_id TEXT NOT NULL, invoice_number TEXT NOT NULL UNIQUE, customer_name TEXT, customer_email TEXT, customer_phone TEXT, total_amount REAL NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (sale_id) REFERENCES sales(id));


-- Table: sales
CREATE TABLE sales (
        id TEXT PRIMARY KEY,
        invoice_number TEXT NOT NULL,
        seller_name TEXT,
        customer_name TEXT NOT NULL,
        customer_phone TEXT,
        items TEXT NOT NULL,
        total_amount REAL NOT NULL,
        sale_type TEXT DEFAULT 'cart',
        status TEXT DEFAULT 'Pendiente',
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      , seller_id TEXT, series_id TEXT);

-- Datos (7 registros)

-- Table: voided_sales
CREATE TABLE voided_sales (
        sale_id TEXT PRIMARY KEY,
        reason TEXT,
        voided_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (sale_id) REFERENCES sales(id)
      );


-- Table: banners
CREATE TABLE banners (
        id TEXT PRIMARY KEY,
        text TEXT NOT NULL,
        type TEXT DEFAULT 'rolling',
        background_color TEXT DEFAULT '#3D1A78',
        text_color TEXT DEFAULT '#ffffff',
        is_active INTEGER DEFAULT 1,
        display_order INTEGER DEFAULT 0,
        link_url TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );

-- Datos (2 registros)

-- Table: advanced_banners
CREATE TABLE advanced_banners (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        image_url TEXT NOT NULL,
        link_url TEXT,
        start_date TEXT,
        end_date TEXT,
        is_active INTEGER DEFAULT 1,
        display_order INTEGER DEFAULT 0,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );

-- Datos (6 registros)

-- Table: stickers
CREATE TABLE stickers (
        id TEXT PRIMARY KEY,
        product_id TEXT NOT NULL,
        message TEXT NOT NULL,
        points INTEGER DEFAULT 6,
        color_start TEXT DEFAULT '#FF006E',
        color_end TEXT DEFAULT '#FFBE0B',
        text_color TEXT DEFAULT '#FFFFFF',
        start_date TEXT NOT NULL,
        end_date TEXT NOT NULL,
        is_active INTEGER DEFAULT 1,
        created_at TEXT DEFAULT (datetime('now')),
        FOREIGN KEY (product_id) REFERENCES catalog(id)
      );

